using System;
using LittleLeo;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "OnStartOfBattleOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/OnStartOfBattle Omen Data")]
public class OnStartOfBattleOmenData : OmenData
{
	[Header("OnStartOfBattle Omen")]
	[SerializeField]
	private bool activeOmenBeforeSaviorPendant;

	[SerializeField]
	private bool brightfulStone;

	protected Action omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate
		{
			StartOfBattleOmenAction(omenInstance)();
		};
		AddToStartOfBattleOmenActions();
	}

	protected Action StartOfBattleOmenAction(OmenInstance omenInstance)
	{
		return delegate
		{
			omenInstance.ActivateOmenFeedback();
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.6f, delegate
			{
				ActivateOmen();
			});
		};
	}

	protected void AddToStartOfBattleOmenActions()
	{
		if (activeOmenBeforeSaviorPendant)
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfBattleBeforeSaviorPendantOmenActions.Add(omenAction);
		}
		else
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfBattleOmenActions.Add(omenAction);
		}
	}

	public override void OmenRemoved()
	{
		if (activeOmenBeforeSaviorPendant)
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfBattleBeforeSaviorPendantOmenActions.Remove(omenAction);
		}
		else
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfBattleOmenActions.Remove(omenAction);
		}
	}

	public override string OmenConvertedDescription()
	{
		return GetStartOfBattleFormatedDescription();
	}

	protected string GetStartOfBattleFormatedDescription()
	{
		return string.Concat(GetStartOfBattleLocalizedDescription(), str2: base.OmenConvertedDescription(), str1: ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace(), str3: brightfulStone ? ("\n" + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("IgnoresHollowSkin")) : "");
	}

	protected string GetOmenConvertedDescriptionWithoutStartOfBattleDescription()
	{
		return base.OmenConvertedDescription();
	}

	public string GetStartOfBattleLocalizedDescription()
	{
		return base.localizationManager.GetLocalizedStartOfBattle();
	}
}
